  "privacy.title": "ਪਰਾਈਵੇਟ ਨੀਤੀ",
  "privacy.effective": "ਪ੍ਰਭਾਵੀ: ਜੂਨ 2026",
  "privacy.collectTitle": "ਅਸੀਂ ਕੀ ਇਕੱਠਾ ਕਰਦੇ ਹਾਂ",
  "privacy.collectBody": "ਡਿਸਪਲੇ ਨਾਮ, ਈਮੇਲ, ਮੋਬਾਈਲ ਨੰਬਰ, ਮਹੀਨਾਵਾਰ ਆਮਦਨ, PAN (ਵਿਕਲਪਿਕ), ਵਿੱਤੀ ਵਚਨਬੱਧਤਾਵਾਂ, ਉਧਾਰ ਰਿਕਾਰਡ, ਮਾਸਿਕ ਸਨੈਪਸ਼ਾਟ।",
  "privacy.whyTitle": "ਅਸੀਂ ਇਸਨੂੰ ਕਿਉਂ ਇਕੱਠਾ ਕਰਦੇ ਹਾਂ",
  "privacy.whyBody": "ਸਿਰਫ਼ ਤੁਹਾਡੇ ਵਿੱਤੀ ਦਬਾਅ ਦੇ ਸਕੋਰ, ਵਚਨਬੱਧਤਾ ਦੇ ਬੋਝ, ਬਚਾਅ ਦੇ ਰਨਵੇ, ਅਤੇ ਉਧਾਰ ਰਿਕਾਰਡਾਂ ਦੀ ਗਣਨਾ ਕਰਨ ਲਈ। ਹੋਰ ਕੋਈ ਮਕਸਦ ਨਹੀਂ।",
  "privacy.whereTitle": "ਜਿੱਥੇ ਇਸਨੂੰ ਸਟੋਰ ਕੀਤਾ ਜਾਂਦਾ ਹੈ",
  "privacy.whereBody": "ਮੁੱਖ ਤੌਰ 'ਤੇ ਤੁਹਾਡੀ ਡਿਵਾਈਸ (ਲੋਕਲ ਸਟੋਰੇਜ) 'ਤੇ। ਵਿਕਲਪਿਕ ਤੌਰ 'ਤੇ Supabase ਵਿੱਚ (ਵਿਸ਼ੇਸ਼ ਤੌਰ 'ਤੇ ਏਨਕ੍ਰਿਪਟਡ, ਪ੍ਰਤੀ ਉਪਭੋਗਤਾ ਅਲੱਗ) ਜਦੋਂ ਕਲਾਉਡ ਸਮਕਾਲੀਕਰਨ ਸਮਰਥਿਤ ਹੁੰਦਾ ਹੈ।",
  "privacy.notTitle": "ਅਸੀਂ ਕੀ ਨਹੀਂ ਕਰਦੇ",
  "privacy.notBody": "ਅਸੀਂ ਤੁਹਾਡਾ ਡੇਟਾ ਨਹੀਂ ਵੇਚਦੇ। ਅਸੀਂ ਕ੍ਰੈਡਿਟ ਬਿਊਰੋ ਨਾਲ ਸਾਂਝਾ ਨਹੀਂ ਕਰਦੇ ਹਾਂ। ਅਸੀਂ ਇਸ਼ਤਿਹਾਰਬਾਜ਼ੀ ਲਈ ਡੇਟਾ ਦੀ ਵਰਤੋਂ ਨਹੀਂ ਕਰਦੇ ਹਾਂ। Razorpay ਭੁਗਤਾਨਾਂ ਨੂੰ ਸੰਭਾਲਦਾ ਹੈ — Perovo ਕਦੇ ਵੀ ਤੁਹਾਡੇ ਕਾਰਡ ਦੇ ਵੇਰਵੇ ਨਹੀਂ ਦੇਖਦਾ।",
  "privacy.rightsTitle": "ਤੁਹਾਡੇ ਅਧਿਕਾਰ (DPDP ਐਕਟ 2023)",
  "privacy.rightsAccess": "ਪਹੁੰਚ: Profile → ਐਕਸਪੋਰਟ ਡੇਟਾ",
  "privacy.rightsCorrection": "ਸੁਧਾਰ: ਐਪ ਵਿੱਚ ਸਿੱਧਾ ਸੰਪਾਦਨ ਕਰੋ",
  "privacy.rightsErasure": "ਮਿਟਾਓ: Profile → ਸਾਰਾ ਡਾਟਾ ਮਿਟਾਓ",
  "privacy.rightsGrievance": "ਸ਼ਿਕਾਇਤ: {email}",
  "privacy.retentionTitle": "ਡਾਟਾ ਧਾਰਨ",
  "privacy.retentionLocal": "ਸਥਾਨਕ ਡਾਟਾ: ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਐਪ ਨੂੰ ਨਹੀਂ ਮਿਟਾਉਂਦੇ ਜਾਂ ਸਾਰਾ ਡਾਟਾ ਮਿਟਾਓ ਦੀ ਵਰਤੋਂ ਨਹੀਂ ਕਰਦੇ।",
