  "insight.lifestyle-inflation": "ਆਵਰਤੀ ਭੁਗਤਾਨ ਇਤਿਹਾਸ ਦੇ {months} ਮਹੀਨਿਆਂ ਵਿੱਚ ਲਗਭਗ {percent}% ਵਧੇ ਹਨ।",
  "insight.subscription-growth": "ਗਾਹਕੀ ਦੇ ਖਰਚੇ ਵੱਧ ਰਹੇ ਹਨ — ਨਵਿਆਉਣ ਅਤੇ ਡੁਪਲੀਕੇਟਸ ਦੀ ਸਮੀਖਿਆ ਕਰੋ।",
  "insight.family-burden": "ਘਰੇਲੂ ਬਿੱਲ ਆਮਦਨ ਦੇ ਇੱਕ ਵੱਡੇ ਹਿੱਸੇ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਹਨ — ਸਾਂਝੀਆਂ ਵਚਨਬੱਧਤਾਵਾਂ ਦੀ ਇਕੱਠੇ ਸਮੀਖਿਆ ਕਰੋ।",
  "insight.family-dependency": "ਘਰ ਇੱਕ ਤੰਗ ਆਮਦਨ-ਤੋਂ-ਬਿੱਲ ਅਨੁਪਾਤ 'ਤੇ ਨਿਰਭਰ ਕਰਦਾ ਹੈ - ਹਰ ਕਿਸੇ ਲਈ ਐਮਰਜੈਂਸੀ ਯੋਜਨਾਬੰਦੀ ਦੇ ਮਾਮਲੇ।",
