  "insight.family-renewals": "{count} ਵੱਡੇ ਸਾਲਾਨਾ ਜਾਂ ਬੀਮਾ ਬਿੱਲ ਆ ਰਹੇ ਹਨ — ਉਹਨਾਂ ਮਹੀਨਿਆਂ ਲਈ ਨਕਦ ਯੋਜਨਾ ਬਣਾਓ।",
  "insight.family-income-concentration": "ਇੱਕ ਆਮਦਨ ਵਰਤਮਾਨ ਵਿੱਚ ਪਰਿਵਾਰ ਦੇ ਦਬਾਅ ਦੇ {pct}% ਦਾ ਸਮਰਥਨ ਕਰਦੀ ਹੈ — ਜੋਖਿਮ ਫੈਲਾਓ ਜਿੱਥੇ ਤੁਸੀਂ ਕਰ ਸਕਦੇ ਹੋ।",
  "insight.family-dependency-burden": "{count} ਲੋਕ ਇਸ ਪਰਿਵਾਰ 'ਤੇ ਨਿਰਭਰ ਕਰਦੇ ਹਨ — ਸੰਕਟਕਾਲੀਨ ਯੋਜਨਾਬੰਦੀ ਹਰ ਕਿਸੇ ਦੀ ਰੱਖਿਆ ਕਰਦੀ ਹੈ।",
  "insight.family-single-earner-risk": "ਇੱਕ ਸਿੰਗਲ ਕਮਾਉਣ ਵਾਲਾ {dependents} ਨਿਰਭਰ (ਆਂ) ਦਾ ਸਮਰਥਨ ਕਰਦਾ ਹੈ — ਆਮਦਨੀ ਦੇ ਝਟਕਿਆਂ ਲਈ ਬਫਰ ਬਣਾਓ।",
